-- Sprint 80: governed buyer profiles, matching signals, traceability and smart shortlists.
create table if not exists public.buyer_property_profiles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),customer_id uuid not null,lead_id uuid,opportunity_id uuid,budget_min numeric,budget_max numeric,currency char(3) not null default'USD',cities text[] not null default'{}',localities text[] not null default'{}',project_ids uuid[] not null default'{}',developers text[] not null default'{}',property_types text[] not null default'{}',bedrooms integer,bathrooms integer,area_min numeric,area_max numeric,floor_preference text,facing text[] not null default'{}',parking integer,furnishing text check(furnishing in('furnished','semi-furnished','unfurnished')),intent text check(intent in('investment','self-use')),possession_timeline date,construction_preference text check(construction_preference in('ready-to-move','under-construction','either')),amenities text[] not null default'{}',proximity jsonb not null default'{}',lifestyle text[] not null default'{}',notes text,created_by uuid not null default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,check(budget_min is null or budget_max is null or budget_min<=budget_max),check(area_min is null or area_max is null or area_min<=area_max));
create table if not exists public.property_match_signals(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),profile_id uuid not null references public.buyer_property_profiles(id)on delete cascade,project_id uuid,unit_id uuid,recommendation_id text,signal_type text not null check(signal_type in('viewed','rejected','accepted','favorited','shortlisted','visit-completed')),popularity_score integer check(popularity_score between 0 and 100),source_type text not null check(source_type in('crm','site-visit','inventory','user')),source_id uuid,created_by uuid not null default auth.uid(),created_at timestamptz not null default now());
create table if not exists public.property_match_runs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),profile_id uuid not null references public.buyer_property_profiles(id),provider_id text not null,provider_version text not null,inventory_version text not null,weights jsonb not null,generated_count integer not null,created_by uuid not null default auth.uid(),created_at timestamptz not null default now());
create table if not exists public.property_match_results(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),run_id uuid not null references public.property_match_runs(id)on delete cascade,profile_id uuid not null references public.buyer_property_profiles(id),project_id uuid not null,unit_id uuid not null,score integer not null check(score between 0 and 100),confidence integer not null check(confidence between 0 and 100),factors jsonb not null,reasons jsonb not null,strengths jsonb not null,tradeoffs jsonb not null,availability text not null,recommendation_only boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.property_shortlists(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),profile_id uuid not null references public.buyer_property_profiles(id)on delete cascade,name text not null,unit_ids uuid[] not null default'{}',favorite_unit_ids uuid[] not null default'{}',shared_internally boolean not null default false,export_status text not null default'placeholder',created_by uuid not null default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.property_match_audit(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),profile_id uuid,recommendation_id text,action text not null,actor_id uuid default auth.uid(),metadata jsonb not null default'{}',occurred_at timestamptz not null default now());
create index if not exists buyer_profiles_tenant_idx on public.buyer_property_profiles(workspace_id,customer_id,lead_id,opportunity_id);create index if not exists match_signals_profile_idx on public.property_match_signals(workspace_id,profile_id,signal_type,created_at desc);create index if not exists match_results_profile_idx on public.property_match_results(workspace_id,profile_id,score desc);create index if not exists shortlists_profile_idx on public.property_shortlists(workspace_id,profile_id,created_at desc);create index if not exists match_audit_trace_idx on public.property_match_audit(workspace_id,profile_id,occurred_at desc);
create or replace function public.property_match_member(p_organization_id uuid,p_workspace_id uuid)returns boolean language sql stable security definer set search_path=public as $$select public.is_organization_member(p_organization_id)and exists(select 1 from workspace_members wm where wm.organization_id=p_organization_id and wm.workspace_id=p_workspace_id and wm.user_id=auth.uid()and wm.status='active')$$;create or replace function public.property_match_can_manage(p_organization_id uuid,p_workspace_id uuid)returns boolean language sql stable security definer set search_path=public as $$select property_match_member(p_organization_id,p_workspace_id)and exists(select 1 from organization_members om left join roles r on r.id=om.role_id where om.organization_id=p_organization_id and om.user_id=auth.uid()and om.status='active'and r.code in('organization_owner','organization_admin','administrator','sales_manager','sales_agent','project_manager','marketing'))$$;
alter table public.buyer_property_profiles enable row level security;alter table public.property_match_signals enable row level security;alter table public.property_match_runs enable row level security;alter table public.property_match_results enable row level security;alter table public.property_shortlists enable row level security;alter table public.property_match_audit enable row level security;
do $$declare t text;begin foreach t in array array['buyer_property_profiles','property_match_signals','property_match_runs','property_match_results','property_shortlists','property_match_audit']loop execute format('create policy %I on public.%I for select to authenticated using(public.property_match_member(organization_id,workspace_id))',t||'_read',t);execute format('create policy %I on public.%I for insert to authenticated with check(public.property_match_can_manage(organization_id,workspace_id))',t||'_create',t);execute format('create policy %I on public.%I for update to authenticated using(public.property_match_can_manage(organization_id,workspace_id)) with check(public.property_match_can_manage(organization_id,workspace_id))',t||'_update',t);execute format('create policy %I on public.%I for delete to authenticated using(public.property_match_can_manage(organization_id,workspace_id))',t||'_delete',t);end loop;end$$;
create or replace function public.save_property_shortlist(p_workspace_id uuid,p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare v_org uuid;v_profile buyer_property_profiles%rowtype;v_id uuid;begin select organization_id into v_org from workspace_members where workspace_id=p_workspace_id and user_id=auth.uid()and status='active';if v_org is null or not property_match_can_manage(v_org,p_workspace_id)then raise exception'not authorized';end if;select*into v_profile from buyer_property_profiles where id=(p_input->>'profileId')::uuid and organization_id=v_org and workspace_id=p_workspace_id;if v_profile.id is null then raise exception'invalid buyer profile';end if;insert into property_shortlists(organization_id,workspace_id,profile_id,name,unit_ids,favorite_unit_ids)values(v_org,p_workspace_id,v_profile.id,left(trim(p_input->>'name'),120),coalesce(array(select jsonb_array_elements_text(coalesce(p_input->'unitIds','[]'))::uuid),'{}'),coalesce(array(select jsonb_array_elements_text(coalesce(p_input->'favoriteUnitIds','[]'))::uuid),'{}'))returning id into v_id;insert into property_match_audit(organization_id,workspace_id,profile_id,action,metadata)values(v_org,p_workspace_id,v_profile.id,'shortlist.created',jsonb_build_object('shortlist_id',v_id));return v_id;end$$;revoke all on function public.save_property_shortlist(uuid,jsonb)from public;grant execute on function public.save_property_shortlist(uuid,jsonb)to authenticated;
